class Solution:
    def shortestPath(self, n: int, edges: List[List[int]], labels: str, k: int) -> int:
        graph = {}
        for u, v, w in edges:
            if u not in graph:
                graph[u] = []
            graph[u].append((v, w))
        heap = [(0, 0, 1)]
        visited = set()

        while heap:
            cost, node, count = heapq.heappop(heap)

            if node == n - 1:
                return cost
            if (node, count) in visited:
                continue
            visited.add((node, count))

            for next, w in graph.get(node, []):
                newCount = 1
                if labels[next] == labels[node]:
                    newCount += count

                if newCount <= k and (next, newCount) not in visited:
                    heapq.heappush(heap, (cost + w, next, newCount))

        return -1
